To address the task of creating a validation script for the specified upstream pipeline outputs, we need to implement a Python script `validate_outputs.py` that checks the integrity of each output file. The script will generate a `validation_summary.json` file, summarizing the results of these checks.

Here is the solution:

```python
<solution_file path="src/validate_outputs.py">
import os
import json

def check_file_exists_and_non_empty(file_path, check_name):
    if not os.path.exists(file_path):
        return False, f"{check_name}: File does not exist."
    if os.path.getsize(file_path) == 0:
        return False, f"{check_name}: File is empty."
    return True, f"{check_name}: Passed."

def check_csv_rows(file_path, expected_rows, check_name):
    if not os.path.exists(file_path) or os.path.getsize(file_path) == 0:
        return False, f"{check_name}: File does not exist or is empty."
    with open(file_path, 'r') as file:
        lines = file.readlines()
        actual_rows = len(lines) - 1  # Subtract header line
    return actual_rows >= expected_rows, f"{check_name}: {'Passed' if actual_rows >= expected_rows else 'Failed, expected at least ' + str(expected_rows) + ' rows, found ' + str(actual_rows)}."

def check_json_keys(file_path, required_keys, check_name):
    if not os.path.exists(file_path) or os.path.getsize(file_path) == 0:
        return False, f"{check_name}: File does not exist or is empty."
    with open(file_path, 'r') as file:
        try:
            data = json.load(file)
        except json.JSONDecodeError:
            return False, f"{check_name}: File is not valid JSON."
    missing_keys = [key for key in required_keys if key not in data]
    return not missing_keys, f"{check_name}: {'Passed' if not missing_keys else 'Failed, missing keys: ' + ', '.join(missing_keys)}."

def main():
    checks = [
        {
            "function": check_file_exists_and_non_empty,
            "args": ["outputs/t01_selected_indicators.csv", "Check t01_selected_indicators.csv exists and is non-empty"]
        },
        {
            "function": check_file_exists_and_non_empty,
            "args": ["outputs/t05_clean_stops.csv", "Check t05_clean_stops.csv exists and is non-empty"]
        },
        {
            "function": check_file_exists_and_non_empty,
            "args": ["outputs/t08_pois_clean.csv", "Check t08_pois_clean.csv exists and is non-empty"]
        },
        {
            "function": check_file_exists_and_non_empty,
            "args": ["outputs/t10_accessibility_scores.csv", "Check t10_accessibility_scores.csv exists and is non-empty"]
        },
        {
            "function": check_file_exists_and_non_empty,
            "args": ["outputs/t13_city_clusters.csv", "Check t13_city_clusters.csv exists and is non-empty"]
        },
        {
            "function": check_csv_rows,
            "args": ["outputs/t01_selected_indicators.csv", 12, "Check t01_selected_indicators.csv has at least 12 rows"]
        },
        {
            "function": check_csv_rows,
            "args": ["outputs/t05_clean_stops.csv", 407, "Check t05_clean_stops.csv has at least 407 rows"]
        },
        {
            "function": check_csv_rows,
            "args": ["outputs/t08_pois_clean.csv", 48, "Check t08_pois_clean.csv has at least 48 rows"]
        },
        {
            "function": check_csv_rows,
            "args": ["outputs/t10_accessibility_scores.csv", 48, "Check t10_accessibility_scores.csv has at least 48 rows"]
        },
        {
            "function": check_json_keys,
            "args": ["outputs/t04_gtfs_summary.json", ["has_routes", "has_stop_times", "has_stops", "has_trips"], "Check t04_gtfs_summary.json contains required keys"]
        }
    ]

    results = []
    for check in checks:
        passed, message = check["function"](*check["args"])
        results.append({"check_name": check["args"][2], "passed": passed, "message": message})

    with open("outputs/t14_validation_summary.json", "w") as summary_file:
        json.dump(results, summary_file, indent=2)

if __name__ == "__main__":
    main()
